   606  /*!
   607   * \brief   pixExtractBarcodeWidths1()
   608   *
   609   * \param[in]    pixs        input image; 8 bpp
   610   * \param[in]    thresh      estimated pixel threshold for crossing
   611   *                           white <--> black; typ. ~120
   612   * \param[in]    binfract    histo binsize as a fraction of minsize; e.g., 0.25
   613   * \param[out]   pnaehist    [optional] histogram of black widths; NULL ok
   614   * \param[out]   pnaohist    [optional] histogram of white widths; NULL ok
   615   * \param[in]    debugflag   use 1 to generate debug output
   616   * \return  nad   numa of barcode widths in encoded integer units,
   617   *                or NULL on error
   618   *
   619   * <pre>
   620   * Notes:
   621   *     (1) The widths are alternating black/white, starting with black
   622   *         and ending with black.
   623   *     (2) This method uses the widths of the bars directly, in terms
   624   *         of the (float) number of pixels between transitions.
   625   *         The histograms of these widths for black and white bars is
   626   *         generated and interpreted.
   627   * </pre>
   628   */
   629  NUMA *
   630  pixExtractBarcodeWidths1(PIX      *pixs,
   631                          l_float32  thresh,
   632                          l_float32  binfract,
   633                          NUMA     **pnaehist,
   634                          NUMA     **pnaohist,
   635                          l_int32    debugflag)
   636  {
   637  NUMA  *nac, *nad;
   638
   639      PROCNAME("pixExtractBarcodeWidths1");
   640
   641      if (!pixs || pixGetDepth(pixs) != 8)
   642          return (NUMA *)ERROR_PTR("pixs undefined or not 8 bpp", procName, NULL);
   643
   644          /* Get the best estimate of the crossings, in pixel units */
   645      nac = pixExtractBarcodeCrossings(pixs, thresh, debugflag);
   646
   647          /* Get the array of bar widths, starting with a black bar  */
   648      nad = numaQuantizeCrossingsByWidth(nac, binfract, pnaehist,
   649                                         pnaohist, debugflag);
   650
   651      numaDestroy(&nac);
   652      return nad;
   653  }
