   763  /*------------------------------------------------------------------------*
   764   *                         Average adjacent rasters                       *
   765   *------------------------------------------------------------------------*/
   766  /*!
   767   * \brief   pixAverageRasterScans()
   768   *
   769   * \param[in]    pixs     input image; 8 bpp
   770   * \param[in]    nscans   number of adjacent scans, about the center vertically
   771   * \return  numa of average pixel values across image, or NULL on error
   772   */
   773  static NUMA *
   774  pixAverageRasterScans(PIX     *pixs,
   775                        l_int32  nscans)
   776  {
   777  l_int32     w, h, first, last, i, j, wpl, val;
   778  l_uint32   *line, *data;
   779  l_float32  *array;
   780  NUMA       *nad;
   781
   782      PROCNAME("pixAverageRasterScans");
   783
   784      if (!pixs || pixGetDepth(pixs) != 8)
   785          return (NUMA *)ERROR_PTR("pixs undefined or not 8 bpp", procName, NULL);
   786
   787      pixGetDimensions(pixs, &w, &h, NULL);
   788      if (nscans <= h) {
   789          first = 0;
   790          last = h - 1;
   791          nscans = h;
   792      } else {
   793          first = (h - nscans) / 2;
   794          last = first + nscans - 1;
   795      }
   796
   797      nad = numaCreate(w);
   798      numaSetCount(nad, w);
   799      array = numaGetFArray(nad, L_NOCOPY);
   800      wpl = pixGetWpl(pixs);
   801      data = pixGetData(pixs);
   802      for (j = 0; j < w; j++) {
   803          for (i = first; i <= last; i++) {
   804              line = data + i * wpl;
   805              val = GET_DATA_BYTE(line, j);
   806              array[j] += val;
   807          }
   808          array[j] = array[j] / (l_float32)nscans;
   809      }
   810
   811      return nad;
   812  }
