    79  /*!
    80   * \brief   pixReadStreamSpix()
    81   *
    82   * \param[in]    fp     file stream
    83   * \return  pix, or NULL on error.
    84   *
    85   * <pre>
    86   * Notes:
    87   *      (1) If called from pixReadStream(), the stream is positioned
    88   *          at the beginning of the file.
    89   * </pre>
    90   */
    91  PIX *
    92  pixReadStreamSpix(FILE  *fp)
    93  {
    94  size_t    nbytes;
    95  l_uint8  *data;
    96  PIX      *pix;
    97
    98      PROCNAME("pixReadStreamSpix");
    99
   100      if (!fp)
   101          return (PIX *)ERROR_PTR("stream not defined", procName, NULL);
   102
   103      if ((data = l_binaryReadStream(fp, &nbytes)) == NULL)
   104          return (PIX *)ERROR_PTR("data not read", procName, NULL);
   105      pix = pixReadMemSpix(data, nbytes);
   106      LEPT_FREE(data);
   107      if (!pix)
   108          return (PIX *)ERROR_PTR("pix not made", procName, NULL);
   109      return pix;
   110  }
