   325  /*!
   326   * \brief   pixSerializeToMemory()
   327   *
   328   * \param[in]    pixs     all depths, colormap OK
   329   * \param[out]   pdata    serialized data in memory
   330   * \param[out]   pnbytes  number of bytes in data string
   331   * \return  0 if OK, 1 on error
   332   *
   333   * <pre>
   334   * Notes:
   335   *      (1) This does a fast serialization of the principal elements
   336   *          of the pix, as follows:
   337   *            "spix"    (4 bytes) -- ID for file type
   338   *            w         (4 bytes)
   339   *            h         (4 bytes)
   340   *            d         (4 bytes)
   341   *            wpl       (4 bytes)
   342   *            ncolors   (4 bytes) -- in colormap; 0 if there is no colormap
   343   *            cdata     (4 * ncolors)  -- size of serialized colormap array
   344   *            rdatasize (4 bytes) -- size of serialized raster data
   345   *                                   = 4 * wpl * h
   346   *            rdata     (rdatasize)
   347   * </pre>
   348   */
   349  l_ok
   350  pixSerializeToMemory(PIX        *pixs,
   351                       l_uint32  **pdata,
   352                       size_t     *pnbytes)
   353  {
   354  char      *id;
   355  l_int32    w, h, d, wpl, rdatasize, ncolors, nbytes, index;
   356  l_uint8   *cdata;  /* data in colormap array (4 bytes/color table entry) */
   357  l_uint32  *data;
   358  l_uint32  *rdata;  /* data in pix raster */
   359  PIXCMAP   *cmap;
   360
   361      PROCNAME("pixSerializeToMemory");
   362
   363      if (!pdata || !pnbytes)
   364          return ERROR_INT("&data and &nbytes not both defined", procName, 1);
   365      *pdata = NULL;
   366      *pnbytes = 0;
   367      if (!pixs)
   368          return ERROR_INT("pixs not defined", procName, 1);
   369
   370      pixGetDimensions(pixs, &w, &h, &d);
   371      wpl = pixGetWpl(pixs);
   372      rdata = pixGetData(pixs);
   373      rdatasize = 4 * wpl * h;
   374      ncolors = 0;
   375      cdata = NULL;
   376      if ((cmap = pixGetColormap(pixs)) != NULL)
   377          pixcmapSerializeToMemory(cmap, 4, &ncolors, &cdata);
   378
   379      nbytes = 24 + 4 * ncolors + 4 + rdatasize;
   380      if ((data = (l_uint32 *)LEPT_CALLOC(nbytes / 4, sizeof(l_uint32)))
   381           == NULL) {
   382          LEPT_FREE(cdata);
   383          return ERROR_INT("data not made", procName, 1);
   384      }
   385      *pdata = data;
   386      *pnbytes = nbytes;
   387      id = (char *)data;
   388      id[0] = 's';
   389      id[1] = 'p';
   390      id[2] = 'i';
   391      id[3] = 'x';
   392      data[1] = w;
   393      data[2] = h;
   394      data[3] = d;
   395      data[4] = wpl;
   396      data[5] = ncolors;
   397      if (ncolors > 0)
   398          memcpy(data + 6, cdata, 4 * ncolors);
   399      index = 6 + ncolors;
   400      data[index] = rdatasize;
   401      memcpy(data + index + 1, rdata, rdatasize);
   402
   403  #if  DEBUG_SERIALIZE
   404      lept_stderr("Serialize:   "
   405                  "raster size = %d, ncolors in cmap = %d, total bytes = %d\n",
   406                  rdatasize, ncolors, nbytes);
   407  #endif  /* DEBUG_SERIALIZE */
   408
   409      LEPT_FREE(cdata);
   410      return 0;
   411  }
