   414  /*!
   415   * \brief   pixDeserializeFromMemory()
   416   *
   417   * \param[in]    data     serialized data in memory
   418   * \param[in]    nbytes   number of bytes in data string
   419   * \return  pix, or NULL on error
   420   *
   421   * <pre>
   422   * Notes:
   423   *      (1) See pixSerializeToMemory() for the binary format.
   424   *      (2) Note the image size limits.
   425   * </pre>
   426   */
   427  PIX *
   428  pixDeserializeFromMemory(const l_uint32  *data,
   429                           size_t           nbytes)
   430  {
   431  char      *id;
   432  l_int32    w, h, d, pixdata_size, memdata_size, imdata_size, ncolors;
   433  l_uint32  *imdata;  /* data in pix raster */
   434  PIX       *pix1, *pixd;
   435  PIXCMAP   *cmap;
   436
   437      PROCNAME("pixDeserializeFromMemory");
   438
   439      if (!data)
   440          return (PIX *)ERROR_PTR("data not defined", procName, NULL);
   441      if (nbytes < 28 || nbytes > ((1LL << 31) - 1)) {
   442          L_ERROR("invalid nbytes = %zu\n", procName, nbytes);
   443          return NULL;
   444      }
   445
   446      id = (char *)data;
   447      if (id[0] != 's' || id[1] != 'p' || id[2] != 'i' || id[3] != 'x')
   448          return (PIX *)ERROR_PTR("invalid id string", procName, NULL);
   449      w = data[1];
   450      h = data[2];
   451      d = data[3];
   452      ncolors = data[5];
   453
   454          /* Sanity checks on the amount of image data */
   455      if (w < 1 || w > MaxAllowedWidth)
   456          return (PIX *)ERROR_PTR("invalid width", procName, NULL);
   457      if (h < 1 || h > MaxAllowedHeight)
   458          return (PIX *)ERROR_PTR("invalid height", procName, NULL);
   459      if (1LL * w * h > MaxAllowedArea)
   460          return (PIX *)ERROR_PTR("area too large", procName, NULL);
   461      if (ncolors < 0 || ncolors > 256 || ncolors + 6 >= nbytes/sizeof(l_int32))
   462          return (PIX *)ERROR_PTR("invalid ncolors", procName, NULL);
   463      if ((pix1 = pixCreateHeader(w, h, d)) == NULL)  /* just make the header */
   464          return (PIX *)ERROR_PTR("failed to make header", procName, NULL);
   465      pixdata_size = 4 * h * pixGetWpl(pix1);
   466      memdata_size = nbytes - 24 - 4 * ncolors - 4;
   467      imdata_size = data[6 + ncolors];
   468      pixDestroy(&pix1);
   469      if (pixdata_size != memdata_size || pixdata_size != imdata_size) {
   470          L_ERROR("pixdata_size = %d, memdata_size = %d, imdata_size = %d "
   471                  "not all equal!\n", procName, pixdata_size, memdata_size,
   472                  imdata_size);
   473          return NULL;
   474      }
   475
   476      if ((pixd = pixCreate(w, h, d)) == NULL)
   477          return (PIX *)ERROR_PTR("pix not made", procName, NULL);
   478      if (ncolors > 0) {
   479          cmap = pixcmapDeserializeFromMemory((l_uint8 *)(&data[6]), 4, ncolors);
   480          if (!cmap) {
   481              pixDestroy(&pixd);
   482              return (PIX *)ERROR_PTR("cmap not made", procName, NULL);
   483          }
   484          pixSetColormap(pixd, cmap);
   485      }
   486
   487      imdata = pixGetData(pixd);
   488      memcpy(imdata, data + 7 + ncolors, imdata_size);
   489
   490  #if  DEBUG_SERIALIZE
   491      lept_stderr("Deserialize: "
   492                  "raster size = %d, ncolors in cmap = %d, total bytes = %zu\n",
   493                  imdata_size, ncolors, nbytes);
   494  #endif  /* DEBUG_SERIALIZE */
   495
   496      return pixd;
   497  }

